colossal_mother_glowcap.source:
export const envelope = [27, 40, 27];

export default function build(api) {
  const [W, H, D] = api.size;
  const cx = 13;
  const cz = 13;
  const BASE_Y = 4; // Node-local seat plane is at Y=4

  // --- Palette Definitions ---
  const woodPlanks = api.theme.wood.planks || "minecraft:birch_planks";
  const woodLog = api.theme.wood.log || "minecraft:birch_log";
  const woodStripped = api.theme.wood.stripped || "minecraft:stripped_birch_log";
  const woodSlab = api.theme.wood.slab || "minecraft:birch_slab";
  const woodStairs = api.theme.wood.stairs || "minecraft:birch_stairs";
  const woodFence = api.theme.wood.fence || "minecraft:birch_fence";
  const woodTrapdoor = api.theme.wood.trapdoor || "minecraft:birch_trapdoor";

  const stoneFloor = api.theme.stone.primary || "minecraft:mossy_stone_bricks";
  const stoneAccent = api.theme.stone.accent || "minecraft:stone_bricks";
  const stonePlinth = api.theme.ground.plinth || "minecraft:cobblestone";
  const groundPavement = api.theme.ground.pavement || "minecraft:mossy_cobblestone";

  // Specialized bioluminescent & fungal materials
  const stemBlock = "minecraft:mushroom_stem";
  const capRed = "minecraft:red_mushroom_block";
  const glowLight = "minecraft:shroomlight";
  const frogOchre = "minecraft:ochre_froglight";
  const frogPearlescent = "minecraft:pearlescent_froglight";
  const chain = "minecraft:chain[axis=y]";

  // --- 3D Grid Buffer for strictly bounds-safe deterministic writes ---
  const grid = Array.from({ length: W }, () =>
    Array.from({ length: H }, () => new Array(D).fill(null))
  );

  function put(x, y, z, block) {
    const ix = Math.floor(x);
    const iy = Math.floor(y);
    const iz = Math.floor(z);
    if (ix >= 0 && ix < W && iy >= 0 && iy < H && iz >= 0 && iz < D) {
      grid[ix][iy][iz] = block;
    }
  }

  function withState(blockString, state) {
    if (!blockString) return blockString;
    const bracketIdx = blockString.indexOf("[");
    if (bracketIdx === -1) {
      return `${blockString}[${state}]`;
    }
    const base = blockString.slice(0, bracketIdx);
    const existing = blockString.slice(bracketIdx + 1, -1);
    return `${base}[${existing},${state}]`;
  }

  // --- Mathematical Profiles for the Mushroom ---
  function getOuterStemRadius(relY) {
    if (relY <= 3) {
      return 5.8 - relY * 0.4;
    }
    if (relY <= 12) {
      return 4.6 - (relY - 3) * 0.1;
    }
    if (relY <= 18) {
      return 3.7 + (relY - 12) * 0.15;
    }
    const t = (relY - 18) / 6;
    return 4.6 + t * t * 3.4;
  }

  function getInnerStemRadius(relY) {
    if (relY <= 3) return 3.4;
    if (relY <= 12) return 2.8;
    if (relY <= 18) return 2.7 + (relY - 12) * 0.08;
    const t = (relY - 18) / 6;
    return 3.2 + t * t * 1.8;
  }

  function getCapRadius(relY) {
    if (relY < 24 || relY > 35) return 0;
    const t = (35.5 - relY) / 11.5;
    return 12.6 * Math.pow(Math.max(0, t), 0.45);
  }

  // Precomputed glowing spore spots on the outer cap dome
  const spotDefinitions = [
    { relY: 27, angle: 0.5, radius: 1.8 },
    { relY: 30, angle: 1.4, radius: 1.6 },
    { relY: 26, angle: 2.3, radius: 2.0 },
    { relY: 32, angle: 3.1, radius: 1.5 },
    { relY: 28, angle: 3.9, radius: 1.9 },
    { relY: 31, angle: 4.8, radius: 1.7 },
    { relY: 25, angle: 5.6, radius: 2.1 },
    { relY: 33, angle: 0.0, radius: 1.4 },
    { relY: 29, angle: 2.0, radius: 1.7 },
    { relY: 28, angle: 5.2, radius: 1.8 },
  ];

  const domeSpots = spotDefinitions.map((s) => {
    const rAtY = getCapRadius(s.relY) - 0.4;
    return {
      x: cx + rAtY * Math.cos(s.angle),
      y: BASE_Y + s.relY,
      z: cz + rAtY * Math.sin(s.angle),
      radius: s.radius,
    };
  });

  // --- 1. Ground Footing & Flared Roots (Follow Terrain) ---
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dx = x - cx;
      const dz = z - cz;
      const dist = Math.hypot(dx, dz);
      const angle = Math.atan2(dz, dx);

      // 6-lobed root buttresses
      const rootLobe =
        Math.cos(6 * angle) * 1.8 + Math.sin(3 * angle) * 0.7;
      const maxRootR = 5.6 + Math.max(0, rootLobe);

      if (dist <= maxRootR) {
        // Read terrain height under footprint and anchor down
        const terrainH = api.heightAt(x, z);
        const groundY = Math.max(0, Math.min(BASE_Y, BASE_Y + terrainH));

        for (let y = groundY; y <= BASE_Y; y++) {
          if (y === groundY) {
            put(x, y, z, stonePlinth);
          } else if (dist <= 3.8) {
            put(x, y, z, stoneFloor);
          } else {
            put(x, y, z, (dist > 5.0) ? groundPavement : stemBlock);
          }
        }
      }
    }
  }

  // --- 2. Hollow Stipe (Stem) Shell (relY = 0 to 24) ---
  for (let relY = 0; relY <= 24; relY++) {
    const y = BASE_Y + relY;
    const rOut = getOuterStemRadius(relY);
    const rIn = getInnerStemRadius(relY);

    for (let x = 0; x < W; x++) {
      for (let z = 0; z < D; z++) {
        const dx = x - cx;
        const dz = z - cz;
        const angle = Math.atan2(dz, dx);
        // Vertical organic fluting ridges
        const fluting = 0.28 * Math.sin(5 * angle + relY * 0.3);
        const dist = Math.hypot(dx, dz) + fluting;

        if (dist <= rOut && dist >= rIn) {
          // Bioluminescent vertical veins along the stem ridges
          const isVein = Math.sin(4 * angle + relY * 0.5) > 0.82;
          if (isVein && dist > rIn + 0.6) {
            put(x, y, z, (relY % 2 === 0) ? glowLight : frogOchre);
          } else {
            put(x, y, z, stemBlock);
          }
        }
      }
    }
  }

  // --- 3. Internal Floors, Rooms & Clear Air Spaces ---
  // Ground Floor (Y = BASE_Y)
  for (let x = cx - 4; x <= cx + 4; x++) {
    for (let z = cz - 4; z <= cz + 4; z++) {
      const d = Math.hypot(x - cx, z - cz);
      if (d <= 3.6) {
        put(x, BASE_Y, z, (d < 1.5) ? stoneAccent : stoneFloor);
      }
    }
  }
  // Spore Hearth at ground center
  put(cx, BASE_Y, cz, frogOchre);
  put(cx + 1, BASE_Y, cz, withState(woodStairs, "facing=west,half=bottom"));
  put(cx - 1, BASE_Y, cz, withState(woodStairs, "facing=east,half=bottom"));
  put(cx, BASE_Y, cz + 1, withState(woodStairs, "facing=north,half=bottom"));
  put(cx, BASE_Y, cz - 1, withState(woodStairs, "facing=south,half=bottom"));

  // Mid-Level Floor (Y = BASE_Y + 8) - Council Chamber
  for (let x = cx - 4; x <= cx + 4; x++) {
    for (let z = cz - 4; z <= cz + 4; z++) {
      const d = Math.hypot(x - cx, z - cz);
      if (d <= 3.2) {
        // Leave stairwell hatch open at (cx - 2, cz)
        if (!(x === cx - 2 && (z === cz || z === cz + 1))) {
          put(x, BASE_Y + 8, z, (d < 1.2) ? woodStripped : woodPlanks);
        }
      }
    }
  }

  // Upper Level Floor (Y = BASE_Y + 15) - High Sanctuary
  for (let x = cx - 4; x <= cx + 4; x++) {
    for (let z = cz - 4; z <= cz + 4; z++) {
      const d = Math.hypot(x - cx, z - cz);
      if (d <= 3.4) {
        // Center opening for pendant lantern and stair cutout
        if (d > 1.0 && !(x === cx + 1 && z === cz + 1)) {
          put(x, BASE_Y + 15, z, woodPlanks);
        }
      }
    }
  }

  // High Council Rotunda Walkway (Y = BASE_Y + 21)
  for (let x = cx - 6; x <= cx + 6; x++) {
    for (let z = cz - 6; z <= cz + 6; z++) {
      const d = Math.hypot(x - cx, z - cz);
      if (d >= 2.6 && d <= 5.4) {
        put(x, BASE_Y + 21, z, woodPlanks);
        if (d >= 5.0) {
          put(x, BASE_Y + 22, z, woodFence);
        }
      }
    }
  }
  // Central Spore Shrine on Rotunda
  put(cx, BASE_Y + 21, cz, frogPearlescent);
  put(cx, BASE_Y + 22, cz, frogPearlescent);
  put(cx, BASE_Y + 23, cz, glowLight);
  put(cx + 1, BASE_Y + 22, cz, woodFence);
  put(cx - 1, BASE_Y + 22, cz, woodFence);
  put(cx, BASE_Y + 22, cz + 1, woodFence);
  put(cx, BASE_Y + 22, cz - 1, woodFence);

  // --- 4. Spiral Staircases Connecting Levels ---
  // Stair 1: Ground to Council (Y = BASE_Y + 1 to BASE_Y + 8)
  const stair1Steps = [
    { x: cx + 2, z: cz - 1, y: BASE_Y + 1, facing: "south" },
    { x: cx + 2, z: cz,     y: BASE_Y + 2, facing: "south" },
    { x: cx + 2, z: cz + 1, y: BASE_Y + 3, facing: "west" },
    { x: cx + 1, z: cz + 2, y: BASE_Y + 4, facing: "west" },
    { x: cx,     z: cz + 2, y: BASE_Y + 5, facing: "north" },
    { x: cx - 1, z: cz + 2, y: BASE_Y + 6, facing: "north" },
    { x: cx - 2, z: cz + 1, y: BASE_Y + 7, facing: "north" },
    { x: cx - 2, z: cz,     y: BASE_Y + 8, facing: "north" },
  ];
  for (const st of stair1Steps) {
    put(st.x, st.y - 1, st.z, woodPlanks);
    put(st.x, st.y, st.z, withState(woodStairs, `facing=${st.facing},half=bottom`));
    // Clearance above step
    put(st.x, st.y + 1, st.z, null);
    put(st.x, st.y + 2, st.z, null);
  }

  // Stair 2: Council to Upper Sanctuary (Y = BASE_Y + 8 to BASE_Y + 15)
  const stair2Steps = [
    { x: cx - 2, z: cz - 1, y: BASE_Y + 9,  facing: "east" },
    { x: cx - 1, z: cz - 2, y: BASE_Y + 10, facing: "east" },
    { x: cx,     z: cz - 2, y: BASE_Y + 11, facing: "south" },
    { x: cx + 1, z: cz - 2, y: BASE_Y + 12, facing: "south" },
    { x: cx + 2, z: cz - 1, y: BASE_Y + 13, facing: "south" },
    { x: cx + 2, z: cz,     y: BASE_Y + 14, facing: "west" },
    { x: cx + 1, z: cz + 1, y: BASE_Y + 15, facing: "west" },
  ];
  for (const st of stair2Steps) {
    put(st.x, st.y - 1, st.z, woodPlanks);
    put(st.x, st.y, st.z, withState(woodStairs, `facing=${st.facing},half=bottom`));
    put(st.x, st.y + 1, st.z, null);
    put(st.x, st.y + 2, st.z, null);
  }

  // Stair 3: Upper Sanctuary to Rotunda (Y = BASE_Y + 15 to BASE_Y + 21)
  const stair3Steps = [
    { x: cx,     z: cz + 2, y: BASE_Y + 16, facing: "north" },
    { x: cx - 1, z: cz + 2, y: BASE_Y + 17, facing: "north" },
    { x: cx - 2, z: cz + 2, y: BASE_Y + 18, facing: "east" },
    { x: cx - 2, z: cz + 1, y: BASE_Y + 19, facing: "east" },
    { x: cx - 3, z: cz,     y: BASE_Y + 20, facing: "south" },
    { x: cx - 3, z: cz - 1, y: BASE_Y + 21, facing: "south" },
  ];
  for (const st of stair3Steps) {
    put(st.x, st.y - 1, st.z, woodPlanks);
    put(st.x, st.y, st.z, withState(woodStairs, `facing=${st.facing},half=bottom`));
    put(st.x, st.y + 1, st.z, null);
    put(st.x, st.y + 2, st.z, null);
  }

  // --- 5. Portals, Entrance Porch & External Balconies ---
  // North Ground Entrance Portal (z facing -Z)
  for (let dy = 1; dy <= 4; dy++) {
    for (let dx = -1; dx <= 1; dx++) {
      put(cx + dx, BASE_Y + dy, cz - 4, null);
      put(cx + dx, BASE_Y + dy, cz - 5, null);
    }
  }
  // Porch awning and deck at North
  for (let px = cx - 2; px <= cx + 2; px++) {
    for (let pz = cz - 7; pz <= cz - 5; pz++) {
      put(px, BASE_Y, pz, woodPlanks);
      // Foundation under porch
      const pGround = Math.max(0, Math.min(BASE_Y, BASE_Y + api.heightAt(px, pz)));
      for (let py = pGround; py < BASE_Y; py++) {
        put(px, py, pz, stonePlinth);
      }
    }
  }
  // Porch Timber Pillars & Awning
  put(cx - 2, BASE_Y + 1, cz - 7, woodLog);
  put(cx - 2, BASE_Y + 2, cz - 7, woodLog);
  put(cx - 2, BASE_Y + 3, cz - 7, woodFence);
  put(cx + 2, BASE_Y + 1, cz - 7, woodLog);
  put(cx + 2, BASE_Y + 2, cz - 7, woodLog);
  put(cx + 2, BASE_Y + 3, cz - 7, woodFence);
  for (let px = cx - 2; px <= cx + 2; px++) {
    put(px, BASE_Y + 4, cz - 6, woodSlab);
    put(px, BASE_Y + 4, cz - 7, woodSlab);
  }
  // Lanterns on Porch
  put(cx - 2, BASE_Y + 4, cz - 7, woodTrapdoor);
  put(cx + 2, BASE_Y + 4, cz - 7, woodTrapdoor);
  put(cx - 2, BASE_Y + 2, cz - 8, frogOchre);
  put(cx + 2, BASE_Y + 2, cz - 8, frogOchre);

  // East Balcony at Council Level (Y = BASE_Y + 8 to BASE_Y + 12)
  // Cut portal through stem
  for (let dy = 1; dy <= 3; dy++) {
    put(cx + 4, BASE_Y + 8 + dy, cz, null);
    put(cx + 4, BASE_Y + 8 + dy, cz - 1, null);
    put(cx + 3, BASE_Y + 8 + dy, cz, null);
  }
  // Cantilevered Balcony Deck
  for (let bx = cx + 4; bx <= cx + 6; bx++) {
    for (let bz = cz - 1; bz <= cz + 1; bz++) {
      put(bx, BASE_Y + 8, bz, woodPlanks);
      // Support brackets underneath
      put(bx, BASE_Y + 7, bz, withState(woodStairs, "facing=east,half=top"));
    }
  }
  // Balcony Fence Railings
  for (let bz = cz - 1; bz <= cz + 1; bz++) {
    put(cx + 6, BASE_Y + 9, bz, woodFence);
  }
  put(cx + 4, BASE_Y + 9, cz - 1, woodFence);
  put(cx + 5, BASE_Y + 9, cz - 1, woodFence);
  put(cx + 4, BASE_Y + 9, cz + 1, woodFence);
  put(cx + 5, BASE_Y + 9, cz + 1, woodFence);
  // Balcony Spore Lamp
  put(cx + 6, BASE_Y + 11, cz, woodFence);
  put(cx + 6, BASE_Y + 10, cz, chain);
  put(cx + 6, BASE_Y + 9, cz, frogPearlescent);

  // South Lookout Perch at Upper Sanctuary (Y = BASE_Y + 15..18)
  for (let dy = 1; dy <= 3; dy++) {
    put(cx, BASE_Y + 15 + dy, cz + 3, null);
    put(cx, BASE_Y + 15 + dy, cz + 4, null);
  }
  for (let sx = cx - 1; sx <= cx + 1; sx++) {
    for (let sz = cz + 4; sz <= cz + 5; sz++) {
      put(sx, BASE_Y + 15, sz, woodPlanks);
      put(sx, BASE_Y + 14, sz, withState(woodStairs, "facing=south,half=top"));
    }
    put(sx, BASE_Y + 16, cz + 5, woodFence);
  }
  put(cx - 1, BASE_Y + 16, cz + 4, woodFence);
  put(cx + 1, BASE_Y + 16, cz + 4, woodFence);

  // --- 6. Underside Gills Fan Blades (relY = 22 to 26) ---
  for (let relY = 22; relY <= 26; relY++) {
    const y = BASE_Y + relY;
    const rCapAtY = Math.max(6.5, getCapRadius(Math.max(24, relY)));
    const rStemAtY = getOuterStemRadius(relY);

    for (let x = 0; x < W; x++) {
      for (let z = 0; z < D; z++) {
        const dx = x - cx;
        const dz = z - cz;
        const dist = Math.hypot(dx, dz);
        const angle = Math.atan2(dz, dx);

        if (dist >= rStemAtY - 0.5 && dist <= rCapAtY) {
          // 16 radiating gill fins
          const gillWave = Math.abs(Math.sin(8 * angle));
          if (gillWave > 0.68) {
            put(x, y, z, stemBlock);
          } else if (gillWave < 0.18 && dist > 5.5 && (relY === 23 || relY === 24)) {
            // Glowing spore veins between gills
            put(x, y, z, (Math.floor(dist + angle * 3) % 2 === 0) ? frogPearlescent : glowLight);
          }
        }
      }
    }
  }

  // --- 7. The Grand Mushroom Cap Dome (relY = 24 to 35) ---
  for (let relY = 24; relY <= 35; relY++) {
    const y = BASE_Y + relY;
    const rOut = getCapRadius(relY);
    // Dome shell thickness
    const rIn = (relY <= 25) ? (rOut - 1.2) : (relY <= 33 ? (rOut - 1.6) : 0);

    for (let x = 0; x < W; x++) {
      for (let z = 0; z < D; z++) {
        const dx = x - cx;
        const dz = z - cz;
        const dist = Math.hypot(dx, dz);

        if (dist <= rOut && dist >= rIn) {
          // Check proximity to glowing spore spots
          let isSpot = false;
          for (const sp of domeSpots) {
            const dSpot = Math.hypot(x - sp.x, y - sp.y, z - sp.z);
            if (dSpot <= sp.radius) {
              isSpot = true;
              break;
            }
          }

          if (isSpot) {
            put(x, y, z, ((x + y + z) % 2 === 0) ? frogOchre : glowLight);
          } else {
            put(x, y, z, capRed);
          }
        }
      }
    }
  }

  // Apex Spore Vent / Crown (Y = BASE_Y + 35 = 39)
  put(cx, BASE_Y + 35, cz, frogPearlescent);
  put(cx + 1, BASE_Y + 35, cz, withState(woodTrapdoor, "half=bottom"));
  put(cx - 1, BASE_Y + 35, cz, withState(woodTrapdoor, "half=bottom"));
  put(cx, BASE_Y + 35, cz + 1, withState(woodTrapdoor, "half=bottom"));
  put(cx, BASE_Y + 35, cz - 1, withState(woodTrapdoor, "half=bottom"));

  // --- 8. Cascading Spore Lanterns Dangling from Cap Rim ---
  const lanternCount = 12;
  for (let i = 0; i < lanternCount; i++) {
    const angle = (i * 2 * Math.PI) / lanternCount + 0.18;
    const rimR = 11.8;
    const lx = Math.round(cx + rimR * Math.cos(angle));
    const lz = Math.round(cz + rimR * Math.sin(angle));
    const dropLen = 3 + ((i * 5 + 2) % 6); // Varied drop lengths 3 to 7
    const startY = BASE_Y + 23;
    const endY = startY - dropLen;

    // Anchor to underside rim
    put(lx, startY, lz, woodFence);
    for (let ly = startY - 1; ly > endY; ly--) {
      put(lx, ly, lz, chain);
    }
    // Glowing spore lantern pod
    const lanternMat = (i % 3 === 0)
      ? frogPearlescent
      : ((i % 2 === 0) ? glowLight : frogOchre);
    put(lx, endY, lz, lanternMat);
    put(lx, endY - 1, lz, chain);
  }

  // --- 9. Final Grid Emission to Api ---
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const block = grid[x][y][z];
        if (block !== null) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  // --- 10. Return Result ---
  return {
    name: "Colossal Mother Glowcap",
    seatY: BASE_Y,
    anchors: {
      front: [cx, BASE_Y, 0],
      door: [cx, BASE_Y, cz - 6],
      summit: [cx, BASE_Y + 35, cz],
      council: [cx, BASE_Y + 8, cz],
      overlook: [cx + 6, BASE_Y + 9, cz],
    },
    interiors: [
      {
        min: [cx - 3, BASE_Y + 1, cz - 3],
        max: [cx + 3, BASE_Y + 7, cz + 3],
        kind: "hall",
      },
      {
        min: [cx - 3, BASE_Y + 9, cz - 3],
        max: [cx + 3, BASE_Y + 14, cz + 3],
        kind: "quarters",
      },
      {
        min: [cx - 3, BASE_Y + 16, cz - 3],
        max: [cx + 3, BASE_Y + 21, cz + 3],
        kind: "vault",
      },
    ],
  };
}

