export const envelope = [13, 17, 13];

export default function build(api) {
  const [W, H, D] = api.size;
  const rng = () => api.random();
  const inst = api.instance ? api.instance.index : 0;

  // Theme palettes with safe fallbacks
  const wood = api.theme?.wood || {};
  const planks = wood.planks || "minecraft:spruce_planks";
  const log = wood.log || "minecraft:spruce_log";
  const stripped = wood.stripped || "minecraft:stripped_spruce_log";
  const fence = wood.fence || "minecraft:spruce_fence";
  const slab = wood.slab || "minecraft:spruce_slab";
  const stairs = wood.stairs || "minecraft:spruce_stairs";
  const trapdoor = wood.trapdoor || "minecraft:spruce_trapdoor";

  const ground = api.theme?.ground || {};
  const plinth = ground.plinth || "minecraft:mossy_cobblestone";

  // Fungal and bioluminescent blocks
  const stem = "minecraft:mushroom_stem";
  const capRed = "minecraft:red_mushroom_block";
  const capBrown = "minecraft:brown_mushroom_block";
  const shroomlight = "minecraft:shroomlight";
  const chain = "minecraft:chain";

  // Block grid write helper with strict boundary check
  function set(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(Math.floor(x), Math.floor(y), Math.floor(z), block);
    }
  }

  // Column downward grounding helper
  function fillToGround(x, startY, z, primaryBlock, plinthBlock = plinth) {
    const h = api.heightAt(x, z);
    const bottomY = Math.min(0, Math.floor(h));
    for (let y = startY; y >= bottomY; y--) {
      if (y >= 0 && y < H) {
        if (y <= 1 && plinthBlock) {
          set(x, y, z, plinthBlock);
        } else {
          set(x, y, z, primaryBlock);
        }
      }
    }
  }

  // --- Instance Variations ---
  const isRedCap = inst % 2 === 0;
  const mainCap = isRedCap ? capRed : capBrown;
  const stalkShiftX = (inst % 3 === 1) ? 1 : (inst % 3 === 2 ? -1 : 0);
  const stalkShiftZ = (inst % 2 === 1) ? 1 : 0;
  const hasSideShelf = (inst % 3 !== 1);
  const floorY = 5;
  const podCeilY = 9;

  // Pod Center & Giant Stalk Center
  const podCx = 5;
  const podCz = 6;
  const stalkBaseX = 8 + stalkShiftX;
  const stalkBaseZ = 7 + stalkShiftZ;

  // ==========================================
  // 1. GIANT MUSHROOM STALK (Ground to Canopy)
  // ==========================================
  for (let y = 0; y <= 15; y++) {
    // Slight organic curving of the stalk
    const curveOffset = Math.sin((y / 15) * Math.PI) * 0.8;
    const sx = Math.round(stalkBaseX - curveOffset * 0.5);
    const sz = Math.round(stalkBaseZ - curveOffset * 0.3);

    const stalkCross = [
      [sx, sz],
      [sx + 1, sz],
      [sx - 1, sz],
      [sx, sz + 1],
      [sx, sz - 1]
    ];

    for (const [x, z] of stalkCross) {
      if (y === 0) {
        fillToGround(x, 0, z, stem);
      } else {
        set(x, y, z, stem);
      }
    }
  }

  // Stalk roots flaring out at the base
  const rootOffsets = [
    [stalkBaseX + 2, stalkBaseZ],
    [stalkBaseX - 2, stalkBaseZ],
    [stalkBaseX, stalkBaseZ + 2],
    [stalkBaseX + 1, stalkBaseZ - 1]
  ];
  for (const [rx, rz] of rootOffsets) {
    fillToGround(rx, 1, rz, stem);
  }

  // ==========================================
  // 2. POD SUSPENSION STILTS & UNDER-BRACING
  // ==========================================
  const podCorners = [
    [3, 4],
    [7, 4],
    [3, 8],
    [7, 8]
  ];

  for (const [cx, cz] of podCorners) {
    fillToGround(cx, floorY - 1, cz, log);
    // Decorative support brackets
    set(cx, floorY - 1, cz, stairs);
  }

  // Under-floor wooden framework
  for (let x = 3; x <= 7; x++) {
    for (let z = 4; z <= 8; z++) {
      if ((x === 3 || x === 7 || z === 4 || z === 8)) {
        set(x, floorY - 1, z, stripped);
      }
    }
  }

  // ==========================================
  // 3. DWELLING POD (Floor, Walls, Ceiling)
  // ==========================================
  // Floor (y = 5)
  for (let x = 3; x <= 7; x++) {
    for (let z = 4; z <= 8; z++) {
      set(x, floorY, z, planks);
    }
  }

  // Pod Outer Shell & Walls (y = 6, 7, 8)
  for (let y = floorY + 1; y < podCeilY; y++) {
    for (let x = 3; x <= 7; x++) {
      for (let z = 4; z <= 8; z++) {
        const isCorner = (x === 3 || x === 7) && (z === 4 || z === 8);
        const isWall = (x === 3 || x === 7 || z === 4 || z === 8);

        if (isCorner) {
          set(x, y, z, log);
        } else if (isWall) {
          // Window openings
          if (y === floorY + 2 && (x === 3 || z === 8)) {
            set(x, y, z, fence);
          } else if (z === 4 && x === 5) {
            // Doorway entrance (open standable)
            set(x, y, z, "minecraft:air");
          } else if (x === 7 && z === 6 && y === floorY + 2) {
            set(x, y, z, shroomlight);
          } else {
            set(x, y, z, planks);
          }
        } else {
          // Hollow Interior Space
          set(x, y, z, "minecraft:air");
        }
      }
    }
  }

  // Pod Ceiling / Roof (y = 9)
  for (let x = 3; x <= 7; x++) {
    for (let z = 4; z <= 8; z++) {
      set(x, podCeilY, z, planks);
    }
  }
  // Roof Eaves Trim
  for (let x = 2; x <= 8; x++) {
    for (let z = 3; z <= 9; z++) {
      if (x === 2 || x === 8 || z === 3 || z === 9) {
        if ((x >= 3 && x <= 7) || (z >= 4 && z <= 8)) {
          set(x, podCeilY, z, slab);
        }
      }
    }
  }

  // ==========================================
  // 4. BALCONIES & BRACKET FUNGI PLATFORMS
  // ==========================================
  // Front Porch (North)
  for (let x = 4; x <= 6; x++) {
    for (let z = 2; z <= 3; z++) {
      set(x, floorY, z, capBrown);
    }
  }
  // Front Stilts down to ground
  fillToGround(4, floorY - 1, 2, fence);
  fillToGround(6, floorY - 1, 2, fence);

  // Porch Railings (y = 6)
  set(4, floorY + 1, 2, fence);
  set(6, floorY + 1, 2, fence);
  set(4, floorY + 1, 3, fence);
  set(6, floorY + 1, 3, fence);

  // Steps down towards North entrance
  set(5, floorY, 1, stairs);
  fillToGround(5, floorY - 1, 1, plinth);

  // Side Bracket Fungus Shelf (West)
  if (hasSideShelf) {
    const shelfY = floorY + 1;
    for (let x = 1; x <= 2; x++) {
      for (let z = 5; z <= 7; z++) {
        set(x, shelfY, z, capBrown);
      }
    }
    set(1, shelfY, 6, shroomlight);
    set(1, shelfY + 1, 5, fence);
    set(1, shelfY + 1, 7, fence);
    // Bracket support underneath
    set(2, shelfY - 1, 6, stairs);
  }

  // ==========================================
  // 5. GIANT GLOWING MUSHROOM CAP (y = 11 to 16)
  // ==========================================
  const capCenterX = 6;
  const capCenterZ = 6;

  // y=11 & 12: Cap Underside Gills & Bioluminescent Spores
  for (let x = 1; x <= 11; x++) {
    for (let z = 1; z <= 11; z++) {
      const dist = Math.sqrt((x - capCenterX) ** 2 + (z - capCenterZ) ** 2);
      if (dist <= 4.8) {
        // Alternating radiating gills and shroomlights
        if ((x + z) % 3 === 0 && dist > 1.8) {
          set(x, 12, z, shroomlight);
        } else {
          set(x, 12, z, stem);
        }
      }
    }
  }

  // y=13 to 16: Mushroom Cap Dome Geometry
  const capLayers = [
    { y: 13, radius: 5.4, height: 1 },
    { y: 14, radius: 4.8, height: 1 },
    { y: 15, radius: 3.6, height: 1 },
    { y: 16, radius: 2.2, height: 1 }
  ];

  for (const layer of capLayers) {
    for (let x = 0; x <= 12; x++) {
      for (let z = 0; z <= 12; z++) {
        const dist = Math.sqrt((x - capCenterX) ** 2 + (z - capCenterZ) ** 2);
        if (dist <= layer.radius) {
          // Polka dot pattern on red mushrooms or organic shading on brown
          if (isRedCap && layer.y >= 14 && ((x * 3 + z * 5 + layer.y) % 7 === 0)) {
            set(x, layer.y, z, stem);
          } else {
            set(x, layer.y, z, mainCap);
          }
        }
      }
    }
  }

  // Top Cap Peak
  set(capCenterX, 16, capCenterZ, mainCap);

  // ==========================================
  // 6. SUSPENSION CABLES & HANGING SPORE LANTERNS
  // ==========================================
  // Chains suspending pod corners from giant cap underside
  const cableCorners = [
    [3, 4],
    [7, 4],
    [3, 8],
    [7, 8]
  ];

  for (const [cx, cz] of cableCorners) {
    for (let y = podCeilY + 1; y <= 12; y++) {
      set(cx, y, cz, chain);
    }
  }

  // Hanging Bioluminescent Lantern Pods from Cap Overhang
  const lanternPoints = [
    [2, 3],
    [10, 6],
    [4, 10]
  ];

  for (let i = 0; i < lanternPoints.length; i++) {
    if (i <= (inst % 3) + 1) {
      const [lx, lz] = lanternPoints[i];
      set(lx, 11, lz, chain);
      set(lx, 10, lz, shroomlight);
      set(lx, 9, lz, fence);
    }
  }

  // Dwelling Entrance Anchor & Furnishing Bounds
  return {
    name: "Cap-Suspended Dwelling",
    seatY: 0,
    anchors: {
      front: [5, floorY + 1, 0],
      door: [5, floorY + 1, 3]
    },
    interiors: [
      {
        min: [4, floorY + 1, 5],
        max: [6, podCeilY - 1, 7],
        kind: "quarters"
      }
    ]
  };
}
